require_once __DIR__.'/CompanyProjectDiscussionChanges.php';require_once __DIR__.'/CompanyProjectDiscussionFiles.php';
/** Finite native discussion subresource actions; called only after both controller CSRF checks. */
final class CompanyProjectDiscussionExtrasHttp
{
    private static function upload():array{$f=$_FILES['discussion_file']??null;if(!is_array($f)||($f['error']??null)!==UPLOAD_ERR_OK||!is_string($f['name']??null)||!is_string($f['tmp_name']??null)||!is_int($f['size']??null)||$f['size']<1||$f['size']>2097152||!is_uploaded_file($f['tmp_name']))throw new DomainException('company_project_discussion_invalid');$bytes=file_get_contents($f['tmp_name'],false,null,0,2097153);if(!is_string($bytes)||strlen($bytes)!==$f['size'])throw new DomainException('company_project_discussion_invalid');return [$f['name'],$bytes];}
    private static function fields($c):array{return [$c->input->post('project_id',false),$c->input->post('project_revision',false),$c->input->post('discussion_collection_revision',false),$c->input->post('discussion_id',false),$c->input->post('discussion_revision',false),$c->input->post('discussion_post_id',false),$c->input->post('discussion_post_revision',false)];}
    public static function portal($c,array $session,int $issuer,string $action):void
    {
        if(!in_array($action,['project_discussion_edit','project_discussion_delete','project_discussion_file_upload','project_discussion_file_hide','project_discussion_file_download'],true)){show_404();return;}$project=$c->input->post('project_id',false);$secret=(string)$c->config->item('encryption_key');$files=new CompanyProjectDiscussionFiles($c->db,db_prefix(),$secret);
        try{[$project,$pr,$cr,$thread,$tr,$post,$revision]=self::fields($c);$key=$c->input->post('request_key',false);$file=$c->input->post('file_key',false);if($action==='project_discussion_file_download'){if(!is_string($file))throw new DomainException('company_project_discussion_unavailable');$result=$files->download($session,$issuer,$project,$thread,$post,$file);$files->confirmDownload($session,$issuer,$project,$thread,$post,$result);$meta=$result['file'];$c->output->set_header("Content-Security-Policy: sandbox; default-src 'none'");$c->output->set_header('X-Content-Type-Options: nosniff');$c->output->set_header('Cache-Control: no-store');$c->output->set_header('Content-Disposition: attachment; filename="anexo.'.($meta['mime']==='image/png'?'png':'pdf').'"; filename*=UTF-8\'\''.rawurlencode($meta['filename']));$c->output->set_content_type($meta['mime'])->set_header('Content-Type: '.$meta['mime'])->set_output($result['content']);return;}if(!is_string($key))throw new DomainException('company_project_discussion_invalid');if(in_array($action,['project_discussion_edit','project_discussion_delete'],true)){$op=$action==='project_discussion_edit'?'edit':'delete';$body=$op==='edit'?$c->input->post('discussion_body',false):null;if($op==='edit'&&!is_string($body))throw new DomainException('company_project_discussion_invalid');(new CompanyProjectDiscussionChanges($c->db,db_prefix(),$secret))->contactChange($session,$issuer,$project,$pr,$cr,$thread,$tr,$post,$revision,$op,$body,$key);$query='discussion_change_receipt=';}elseif($action==='project_discussion_file_upload'){[$name,$bytes]=self::upload();$files->contactUpload($session,$issuer,$project,$pr,$cr,$thread,$tr,$post,$revision,$key,$name,$bytes);$query='discussion_file_receipt=';}else{if(!is_string($file))throw new DomainException('company_project_discussion_invalid');$files->contactHide($session,$issuer,$project,$pr,$cr,$thread,$tr,$post,$revision,$file,$key);$query='discussion_file_receipt=';}}
        catch(DomainException $denied){$status=match($denied->getMessage()){'company_project_discussion_stale','company_project_discussion_request_conflict','company_project_discussion_has_replies'=>409,'company_project_discussion_limit','company_operation_file_limit'=>429,'company_project_discussion_invalid','company_operation_file_invalid'=>422,default=>404};if($status===404){show_404();return;}show_error($status===409?'O comentário mudou ou possui respostas. Reabra antes de alterar.':($status===429?'Limite de versões ou de 20 anexos/20 MiB da conversa atingido.':'Envie texto de até8000 bytes, PDF até2 MiB ou PNG/JPEG até512 KiB e1600 pixels.'),$status);return;}
        redirect($c->config->site_url('company_portal/index/'.$issuer).'?operation_kind=projects&resource_id='.IssuerPolicy::id($project).'&'.$query.$key,'location',303);
