    public static function staffDownload($c,int $issuer,int $actor,int $project):void{$file=$c->input->post('file_key',false);if(!is_string($file))throw new DomainException('company_project_discussion_unavailable');$thread=$c->input->post('discussion_id',false);$post=$c->input->post('discussion_post_id',false);$reader=new CompanyProjectDiscussionFiles($c->db,db_prefix());$r=$reader->staffDownload($issuer,$actor,$project,$thread,$post,$file);$reader->confirmStaffDownload($issuer,$actor,$project,$thread,$post,$r);$meta=$r['file'];$c->output->set_header("Content-Security-Policy: sandbox; default-src 'none'");$c->output->set_header('X-Content-Type-Options: nosniff');$c->output->set_header('Cache-Control: no-store');$c->output->set_header('Content-Disposition: attachment; filename="anexo.'.($meta['mime']==='image/png'?'png':'pdf').'"; filename*=UTF-8\'\''.rawurlencode($meta['filename']));$c->output->set_content_type($meta['mime'])->set_header('Content-Type: '.$meta['mime'])->set_output($r['content']);}
    public static function staff($c,int $issuer,int $actor,int $project,string $action,string $key):int
    {
        [, $pr,$cr,$thread,$tr,$post,$revision]=self::fields($c);if(in_array($action,['discussion_edit','discussion_delete'],true)){$op=$action==='discussion_edit'?'edit':'delete';$body=$op==='edit'?$c->input->post('discussion_body',false):null;if($op==='edit'&&!is_string($body))throw new DomainException('company_project_discussion_invalid');(new CompanyProjectDiscussionChanges($c->db,db_prefix()))->staffChange($issuer,$actor,$project,$pr,$cr,$thread,$tr,$post,$revision,$op,$body,$key);}elseif($action==='discussion_file_upload'){[$name,$bytes]=self::upload();(new CompanyProjectDiscussionFiles($c->db,db_prefix()))->staffUpload($issuer,$actor,$project,$pr,$cr,$thread,$tr,$post,$revision,$key,$name,$bytes);}elseif($action==='discussion_file_audience'){$file=$c->input->post('file_key',false);$audience=$c->input->post('discussion_file_audience',false);if(!is_string($file)||!is_string($audience))throw new DomainException('company_project_discussion_invalid');(new CompanyProjectDiscussionFiles($c->db,db_prefix()))->publish($issuer,$actor,$project,$pr,$cr,$thread,$tr,$post,$revision,$file,$audience,$key);}else throw new DomainException('company_project_discussion_invalid');return IssuerPolicy::id($thread);
    }
